#include <stdio.h>
#include <stdlib.h>

int cmp(const void* a, const void* b) {
    return ((int*) a)[1] - ((int*) b)[1];
}

int main() {
    int n;
    scanf("%d", &n);

    int ranges[n][2];
    for(int i=0; i<n; i++) {
        scanf("%d %d", &ranges[i][0], &ranges[i][1]);
        ranges[i][1] += ranges[i][0];
    }

    qsort(ranges, n, sizeof(int*), cmp);

    int t = ranges[0][1];
    int ans = 1;

    for(int i=1; i<n; i++) {
        int l = ranges[i][0];
        int r = ranges[i][1];

        if(l - t >= 15) {
            ans++;
            t = r;
        }
    }

    printf("%d\n", ans);

    return 0;
}
